RestServiceDefinition.SqlExecute:


CREATE TABLE IF NOT EXISTS RoleAndUserId (
    RoleId TEXT,
    UserId TEXT
);

    INSERT INTO RoleAndUserId (UserId, RoleId)
    VALUES('$$id$$', '$$verifiedRoleId$$');

    SELECT UserId, RoleId AS RoleIdNew FROM RoleAndUserId WHERE RoleId = '$$verifiedRoleId$$';
